SELECT time, CAST(metric_0001 AS DOUBLE PRECISION) AS metric_0001, CAST(metric_0556 AS DOUBLE PRECISION) AS metric_0556, CAST(metric_1111 AS DOUBLE PRECISION) AS metric_1111, CAST(metric_1667 AS DOUBLE PRECISION) AS metric_1667, CAST(metric_2222 AS DOUBLE PRECISION) AS metric_2222, CAST(metric_2778 AS DOUBLE PRECISION) AS metric_2778, CAST(metric_3333 AS DOUBLE PRECISION) AS metric_3333, CAST(metric_3889 AS DOUBLE PRECISION) AS metric_3889, CAST(metric_4444 AS DOUBLE PRECISION) AS metric_4444, CAST(metric_5000 AS DOUBLE PRECISION) AS metric_5000 FROM wide5000 WHERE time >= '2024-12-31' AND time < '2025-01-01' ORDER BY time
